function targetHUD(){const el=$('target-hud'),cross=$('combat-crosshair'),active=state==='play'&&!building&&!terrainActive;cross.hidden=true;if(!active){el.hidden=$('interaction').hidden=true;return}const portal=portalNear();if(portal){el.hidden=true;$('interaction').hidden=false;$('interaction').textContent=portal.exit?'[ E ] · Esci':'[ E ] · Entra: '+portal.name;return}if(witchNear()){el.hidden=true;cross.dataset.status='idle';$('interaction').hidden=false;$('interaction').textContent='[ E ] · Parla con la strega';return}const hit=aimedTarget(),r=hit?.target;cross.dataset.status=hit?(hit.valid?'ready':'blocked'):'idle';if(r){el.hidden=false;const hp=targetHealth(r);$('target-name').textContent=resourceNames[r.kind]||r.kind;$('target-hp').textContent=hp+' / '+r.maxHp;$('target-fill').style.width=hp/r.maxHp*100+'%';$('interaction').hidden=false;$('interaction').textContent=hit.valid?(r.kind==='chest'?'[ E ] · Apri forziere':'CLIC / E · Colpisci'):hit.reason;return}const structure=nearStructure();if(structure){el.hidden=false;$('target-name').textContent=PIECES[structure.kind].name;$('target-hp').textContent=PIECES[structure.kind].hp+' PV';$('target-fill').style.width='100%';$('interaction').hidden=false;$('interaction').textContent='[ E ] · '+(structure.kind==='bench'?'Usa banco da lavoro':structure.open?'Chiudi porta':'Apri porta');return}el.hidden=true;const water=!insideInstance&&waterDist(s.x,s.z)<22;$('interaction').hidden=!water;if(water)$('interaction').textContent='[ E ] · Bevi acqua'}
function wolfTick(dt){nightTick(dt);for(const w of wolves){if(w.dead){if(!w.site&&!nightKind(w.kind)&&s.elapsed>=w.respawn){w.dead=false;w.hp=w.maxHp;w.x=w.homeX;w.z=w.homeZ;w.g.visible=true}continue}w.hit=Math.max(0,w.hit-dt);const dx=s.x-w.x,dz=s.z-w.z,d=Math.hypot(dx,dz);w.g.visible=d<90;if(d>100)continue;let vx=0,vz=0;if(passiveKinds.includes(w.kind)&&d<12&&d>.1){vx=-dx/d;vz=-dz/d}else if(!passiveKinds.includes(w.kind)&&d<(nightKind(w.kind)?28:13)&&d>1.2){vx=dx/d;vz=dz/d}else if(d>=(nightKind(w.kind)?28:13)){const tx=w.homeX+Math.sin(s.elapsed*.16+w.homeX)*4-w.x,tz=w.homeZ+Math.cos(s.elapsed*.13+w.homeZ)*4-w.z,dd=Math.hypot(tx,tz);if(dd>.4){vx=tx/dd;vz=tz/dd}}if(insideInstance&&w.site&&d<26&&d>1.2){const next=insideInstance.next(w.x,w.z,s.x,s.z),dd=Math.hypot(next.x-w.x,next.z-w.z);if(dd>.05){vx=(next.x-w.x)/dd;vz=(next.z-w.z)/dd}}const speed=nightKind(w.kind)?3.25:d<13?(passiveKinds.includes(w.kind)?4.7:w.kind==='boar'?2.5:2.9):.8;if(w.hit>.3){vx=-vx;vz=-vz}const nx=clamp(w.x+vx*speed*dt,-LIMIT,LIMIT),nz=clamp(w.z+vz*speed*dt,-LIMIT,LIMIT);if(!blockedByBuild(nx,nz)&&(insideInstance||!w.site||Math.abs(nx-w.homeX)<5&&Math.abs(nz-w.homeZ)<6)){w.x=nx;w.z=nz}w.g.position.set(w.x,height(w.x,w.z),w.z);if(vx||vz)w.g.rotation.y=Math.atan2(vx,vz);w.phase+=dt*(d<13?11:4);w.legs.forEach((leg,i)=>leg.rotation.x=Math.sin(w.phase+(i%2?Math.PI:0)+(i>1?Math.PI:0))*.4);if(!passiveKinds.includes(w.kind)&&d<1.65&&w.hit<=0&&jumpY<.85&&!(insideInstance?!insideInstance.clear(w.x,w.z,s.x,s.z):world.blocked((s.x+w.x)/2,(s.z+w.z)/2))){w.hit=1.25;s.health=clamp(s.health-(nightKind(w.kind)?14:w.kind==='crocodile'?18:w.kind==='boar'?12:9));toast(resourceNames[w.kind]+' ti ha ferito!')}}}
function updateHud(){renderHotbar();$('site-count').textContent=world.sites.filter(q=>s.opened['discover:'+q.id]).length+'/'+world.sites.length;const next=world.sites.filter(q=>!s.opened['discover:'+q.id]).sort((a,b)=>Math.hypot(s.x-a.x,s.z-a.z)-Math.hypot(s.x-b.x,s.z-b.z))[0];$('site-near').textContent=next?'Da scoprire: '+next.name+' · '+Math.round(Math.hypot(s.x-next.x,s.z-next.z))+' m':'Tutti i nuovi luoghi scoperti';$('explored').textContent=s.discoveries.length+'/5';$('night-warning').hidden=!isNight();for(const k of ['health','hunger','thirst','stamina']){$(k+'-value').textContent=Math.ceil(s[k])+'%';$(k+'-bar').style.width=s[k]+'%'}const t=Math.floor(s.time),day=Math.floor(t/1440)+1,hh=Math.floor(t/60)%24,mm=t%60;$('clock').textContent='GIORNO '+day+' · '+String(hh).padStart(2,'0')+':'+String(mm).padStart(2,'0');const loc=landmarks.find(l=>Math.hypot(s.x-l.x,s.z-l.z)<16);$('region').textContent=(loc?.name||biomeAt(s.x,s.z).name).toUpperCase();const inv=s.inventory;if(!s.buildings.some(b=>b.kind==='bench')){$('quest').textContent='Costruisci il banco da lavoro';$('quest-sub').textContent=inv.bench?'Banco pronto · B per posarlo':'C · '+Math.min(4,inv.wood||0)+'/4 legna'}else if(!WEAPONS.some(k=>inv[k])){$('quest').textContent='Crea la tua prima arma';$('quest-sub').textContent='Ascia: '+Math.min(2,inv.wood||0)+'/2 legna · '+Math.min(3,inv.stone||0)+'/3 pietra · '+Math.min(1,inv.fiber||0)+'/1 fibra'}else if(!s.inventory.hammer){$('quest').textContent='Crea un martello';$('quest-sub').textContent='3 legna · 2 pietra'}else if(!s.buildings.some(b=>b.kind==='bench')){$('quest').textContent='Posa un banco da lavoro';$('quest-sub').textContent='B · 4 legna'}else if(!s.buildings.some(b=>b.kind==='roof')){$('quest').textContent='Costruisci il primo riparo';$('quest-sub').textContent='Lavora tavole al banco · B per costruire'}else if(!s.equipped.tunic){$('quest').textContent='Vestiti per la notte';$('quest-sub').textContent='Tunica: '+Math.min(6,inv.fiber||0)+'/6 fibra · '+Math.min(1,inv.hide||0)+'/1 pelle'}else if(!fires.length){$('quest').textContent='Accendi il tuo primo falò';$('quest-sub').textContent='5 legna · 4 pietra'}else{$('quest').textContent='Esplora le antiche rovine';$('quest-sub').textContent=Object.keys(s.opened).length+'/'+loot.length+' forzieri · '+s.kills+' animali sconfitti'}if(insideInstance){$('region').textContent=insideInstance.site.name.toUpperCase();$('site-near').textContent='E · Esci dalla porta iniziale';$('quest').textContent=insideInstance.site.guard?'Esplora le camere e sconfiggi i guardiani':'Esplora l’interno';$('quest-sub').textContent=insideInstance.site.guard?wolves.filter(w=>!w.dead).length+' guardiani rimasti':'Luogo separato dal mondo esterno'}drawMap()}
let mapBackground=null;function drawMap(){const c=$('map'),q=c.getContext('2d');if(insideInstance){q.fillStyle='#171a17';q.fillRect(0,0,140,140);const cells=insideInstance.layout.cells,scale=16,px=x=>70+(x/7)*scale,pz=z=>20+(z/7)*scale;for(const a of cells){if(!insideInstance.visited.has(a.k))continue;q.fillStyle='#7b7867';q.fillRect(px(a.x*7)-7,pz(a.z*7)-7,14,14);for(const k of a.links){const b=insideInstance.layout.map.get(k);if(insideInstance.visited.has(k)){q.strokeStyle='#aaa68e';q.lineWidth=3;q.beginPath();q.moveTo(px(a.x*7),pz(a.z*7));q.lineTo(px(b.x*7),pz(b.z*7));q.stroke()}}}q.fillStyle='#d6b279';q.fillRect(67,17,6,6);q.fillStyle='#fff';q.beginPath();q.arc(px(s.x),pz(s.z),3,0,TAU);q.fill();return}const m=(x)=>70+x/LIMIT*67;if(!mapBackground){mapBackground=document.createElement('canvas');mapBackground.width=mapBackground.height=140;const ctx=mapBackground.getContext('2d');for(let yy=0;yy<140;yy+=5)for(let xx=0;xx<140;xx+=5){const bio=biomeAt((xx-70)/67*LIMIT,(yy-70)/67*LIMIT);ctx.fillStyle='#'+bio.base.toString(16).padStart(6,'0');ctx.fillRect(xx,yy,5,5)}}q.drawImage(mapBackground,0,0);q.strokeStyle='#94a88733';for(let i=10;i<140;i+=20){q.beginPath();q.moveTo(i,0);q.lineTo(i,140);q.moveTo(0,i);q.lineTo(140,i);q.stroke()}q.fillStyle='#4e9499';for(const l of LAKES){q.beginPath();q.arc(m(l.x),m(l.z),l.r/LIMIT*67,0,TAU);q.fill()}q.fillStyle='#dfbe83';for(const l of landmarks.filter(l=>!l.name.includes('Lago'))){q.fillStyle=l.kind?(s.opened['discover:'+l.id]?'#95cb8d':'#efbf72'):'#dfbe83';q.fillRect(m(l.x)-2,m(l.z)-2,4,4)}for(const f of fires){q.fillStyle='#ffb252';q.fillRect(m(f.x)-2,m(f.z)-2,4,4)}q.save();q.translate(m(s.x),m(s.z));q.rotate(-s.yaw);q.fillStyle='#fff2cb';q.beginPath();q.moveTo(0,5);q.lineTo(-4,-4);q.lineTo(4,-4);q.closePath();q.fill();q.restore()}
let benchSession=false;function openBag(mode){if(state!=='play'&&state!=='bag')return;if(building||terrainActive)exitBuild();if(state!=='bag')benchSession=mode==='bench'&&!!nearStructure()&&nearStructure().kind==='bench';state='bag';bagMode=mode==='bench'?'craft':mode;keys.clear();touchMove={x:0,y:0};runTouch=false;$('bag').hidden=false;$('touch').hidden=true;renderBag()}
