function actionButton(parent,label,fn,disabled=false){const b=document.createElement('button');b.className='secondary';b.type='button';b.textContent=label;b.disabled=disabled;b.addEventListener('click',fn);parent.append(b);return b}
function costList(parent,cost){parent.replaceChildren();for(const [id,n] of Object.entries(cost||{})){const d=document.createElement('div');d.className='cost-row'+((s.inventory[id]||0)<n?' missing':'');d.innerHTML=art(id)+'<span>'+ITEMS[id]+'</span><b>'+(s.inventory[id]||0)+' / '+n+'</b>';parent.append(d)}}
function tile(parent,id,name,n,onSelect,locked=false){const b=document.createElement('button');b.type='button';b.className='item-tile'+(locked?' locked':'');b.title=name;b.innerHTML=art(id)+'<span class="tile-name">'+name+'</span>'+(n?'<span class="tile-count">'+n+'</span>':'')+(locked?'<span class="tile-lock">◆</span>':'');b.addEventListener('click',()=>{for(const x of parent.children)x.classList.toggle('selected',x===b);onSelect()});parent.append(b);return b}
function beginBenchPlacement(){if(insideInstance){toast('Posiziona il banco all’esterno.');return}if(!s.inventory.bench)return;if(state==='bag')closeBag();exitBuild();buildKind='bench';building=true;aim=null;$('build-hud').hidden=$('build-crosshair').hidden=false;updateBuild()}
function craftItem(r){if(insideInstance&&['bench','campfire'].includes(r.id)){toast('Crea e posiziona questo oggetto all’esterno.');return}if(!craft(s,r.id,nearFire(),benchSession&&benchNear(s)))return;if(r.id==='bench'){updateHud();save();beginBenchPlacement();return}if(r.id==='campfire'){take(s,'campfire');let x=clamp(s.x+Math.sin(s.yaw)*2,-LIMIT,LIMIT),z=clamp(s.z+Math.cos(s.yaw)*2,-LIMIT,LIMIT);if(!dry(x,z)){x=s.x;z=s.z}s.fires.push({x,z});makeFire(x,z)}$('bag-note').textContent='Creato: '+r.name;updateHud();save();renderBag()}
